// Extraer la intención del output del agente
const output = $input.first().json.output || '';
const inputData = $('Mesocycle_Renewal_Trigger').first().json;

// Buscar el patrón de intención
const intentionMatch = output.match(/INTENCION:(\w+)(?::(\d+))?/);

let intention = 'PREGUNTAR_OPCIONES';
let newDays = null;
let cleanOutput = output;

if (intentionMatch) {
  intention = intentionMatch[1];
  if (intentionMatch[2]) {
    newDays = parseInt(intentionMatch[2]);
  }
  // Limpiar el output removiendo el código de intención
  cleanOutput = output.replace(/INTENCION:\w+(?::\d+)?/g, '').trim();
}

return [{
  json: {
    ...inputData,
    intention,
    newDays,
    agentOutput: cleanOutput,
    rawOutput: output
  }
}];

// Procesar las alternativas y actualizar los ejercicios
const alternatives = $input.all();
const inputData = $('Switch_Intention').first().json;

if (alternatives.length === 0) {
  return [{
    json: {
      ...inputData,
      rotationSuccess: false,
      message: 'No se encontraron ejercicios alternativos disponibles.'
    }
  }];
}

// Construir las queries de actualización
const updates = alternatives.map(alt => {
  return {
    old_exercise_id: alt.json.old_exercise_id,
    new_exercise_id: alt.json.new_exercise_id,
    pattern: alt.json.pattern
  };
});

return [{
  json: {
    ...inputData,
    rotationSuccess: true,
    exerciseUpdates: updates,
    updatesCount: updates.length
  }
}];

