={{ (() => {
  const updates = $json.exerciseUpdates || [];
  if (updates.length === 0) return 'SELECT 1';

  const cases = updates.map(u => 
    `WHEN exercise_id = '${u.old_exercise_id}' THEN '${u.new_exercise_id}'`
  ).join('\n    ');

  const oldIds = updates.map(u => `'${u.old_exercise_id}'`).join(', ');

  return `
    UPDATE workouts
    SET exercise_id = CASE
      ${cases}
      ELSE exercise_id
    END
    WHERE user_id = '${$json.user_id}'
    AND exercise_id IN (${oldIds});

    -- Limpiar schedule
    DELETE FROM user_weekly_schedule WHERE user_id = '${$json.user_id}';

    -- Incrementar mesociclo
    UPDATE users_plans
    SET mesocycle_number = COALESCE(mesocycle_number, 1) + 1,
        last_renewal_date = NOW()
    WHERE user_id = '${$json.user_id}';
  `;
})() }}

